━━━━━━━━━━━━━━━━━━━━━━
・「格子間隔20kmのモデルで表現できる現象の水平スケールとして適切なものを選べ」という問題。格子間隔の数倍から10倍以上のスケールが正解で、格子間隔と同じスケールを選ぶと誤りになる
・「水平分解能を2倍に高めたときの計算量の増加として適切なものを選べ」という問題。水平2方向で4倍、時間ステップ半減で2倍、合わせて約8倍が正解
・「スペクトル法の説明として誤っているものを選べ」という問題。降水などの不連続な分布を扱いにくい点、物理過程は格子点で計算する点が正誤の分かれ目になる
・実技では、モデルの格子間隔を示したうえで「この現象を予測できるか」を判断させる出題がある。積乱雲単体は不可、線状降水帯の環境場は可という切り分けが答案の型

