        body: `▼ゼロから：水平方向は緯度経度で区切れば済みますが、鉛直方向をどう区切るかは悩ましい問題です。高度で区切ると、山の斜面が格子を斜めに横切ってしまい、地面の下に格子点ができてしまいます。そこで考え出されたのが「地形に沿って曲げた座標」です。地面をぴったり座標面のひとつにしてしまえば、下端の境界条件が簡単に書けます。これがシグマ座標で、現在は気圧座標と組み合わせたハイブリッド座標が主流です。

━━━━━━━━━━━━━━━━━━━━━━
🔑 三つの鉛直座標
━━━━━━━━━━━━━━━━━━━━━━
・高度座標（z座標）…実際の高さで区切る。直感的だが山岳で地下格子が生じる
・気圧座標（p座標）…気圧を鉛直座標にする。連続の式が簡単になる利点があるが、地表気圧が変わると下端が動く
・シグマ座標…その地点の気圧を地上気圧で割った値をシグマとする。地表がシグマ＝1、大気上端がシグマ＝0で固定される
→ シグマ座標では地形が座標面に吸収されるので、下端の境界条件は「シグマ方向の速度がゼロ」と書ける

━━━━━━━━━━━━━━━━━━━━━━
🔑 シグマ座標の弱点とハイブリッド座標
━━━━━━━━━━━━━━━━━━━━━━
・弱点…高い山の上空では座標面が大きく波打ち、水平気圧傾度力を二つの大きな項の差として計算するため誤差が出やすい
・対策…下層はシグマ座標的に地形に沿わせ、上層は気圧座標的に水平な面に近づける
→ これがハイブリッド気圧座標。現在の全球モデルの標準
→ 非静力学モデルでは高度ベースの地形追随座標を使う場合もある

【図解】鉛直座標の性質比較
　座標｜下端の扱い｜主な弱点｜
　高度座標｜地形が格子を横切る｜地下格子が生じる｜
　気圧座標｜地上気圧で変動｜地形の表現が困難｜
　シグマ座標｜常にシグマが1｜山岳上空で誤差｜
　ハイブリッド｜下層は地形追随｜実装が複雑｜
　⚠ シグマ座標の面は水平面ではない。等シグマ面上の気温分布を等圧面の気温分布と混同しない

━━━━━━━━━━━━━━━━━━━━━━
🔑 鉛直層の配置
━━━━━━━━━━━━━━━━━━━━━━
・層は等間隔ではなく、地表付近と対流圏界面付近を密にとる
・地表付近を密にする理由…境界層の風速の急変や逆転層を捉えるため
・上端は成層圏やさらに上まで伸ばす。上端付近では波の反射を防ぐ吸収層を置く
・全球モデルの鉛直層数は100層規模、メソモデルでも数十層に達する
→ 鉛直解像度が粗いと、接地逆転層や下層の湿潤層が表現できず、放射霧や下層雲の予測が外れやすい

━━━━━━━━━━━━━━━━━━━━━━
🔑 モデル地形と実際の地形
━━━━━━━━━━━━━━━━━━━━━━
・モデルの地形は格子内の平均標高で表される
・格子20kmの全球モデルでは、日本アルプスの標高は実際より大幅に低く、盆地は浅く均される
・その結果、山越え気流やフェーンの強さ、山岳での降水量が過小に出やすい
→ 格子5kmのメソモデルでは地形がかなり現実に近づき、地形性降水の位置が改善する
→ ただし急峻な地形を無理に表現すると座標面が激しく波打ち、計算が不安定になるため、地形は平滑化して与える
→ 実技では「モデル地形が実際より低いため、山地の降水が過小評価される可能性」といった記述が答案の型になる

━━━━━━━━━━━━━━━━━━━━━━
🔑 鉛直流の表し方
━━━━━━━━━━━━━━━━━━━━━━
・気圧座標系での鉛直流を鉛直p速度と呼び、単位はhPa毎時などで表す
・気圧は上ほど小さいので、上昇流は負の値、下降流は正の値になる
・シグマ座標系ではシグマの時間変化率が鉛直流にあたる
→ 数値予報天気図の鉛直p速度は、負の領域（上昇流）に実線や陰影を付けて表示されることが多い
→ 符号の向きを取り違えると、上昇流域と下降流域を丸ごと逆に読むことになる

━━━━━━━━━━━━━━━━━━━━━━
🔑 頻出のひっかけ
━━━━━━━━━━━━━━━━━━━━━━
・「シグマ座標では地形を考えなくてよい」→ × 地形は座標変換の中に入り込み、気圧傾度力の計算誤差として現れる
・「鉛直層は等間隔に配置する」→ × 地表付近と圏界面付近を密にする
・「気圧座標では地面より下に座標面ができない」→ × 高気圧下の高地などで地下に等圧面が来る場合がある
・「鉛直層を増やせば水平分解能も上がる」→ × 別の話

━━━━━━━━━━━━━━━━━━━━━━
🔑 過去問での問われ方
━━━━━━━━━━━━━━━━━━━━━━
・「地形に沿う鉛直座標の利点として適切なものを選べ」という問題。下端の境界条件が簡単になる点が正解で、気圧傾度力の計算精度が上がるという選択肢は誤り
・「モデルの鉛直層の配置として適切なものを選べ」という問題。地表付近を密にする理由が境界層と逆転層の表現である点を押さえる
・「モデル地形が実際の地形と異なることによる予報への影響を述べよ」という記述問題。山地の標高が低く均されるため上昇流が弱く、地形性降水が過小になると書く
・鉛直p速度の符号を示した図を読ませ、上昇流域を答えさせる出題も多い。負の値が上昇流である点を必ず確認する

★ここだけ暗記
★シグマ＝気圧÷地上気圧、地表で1、上端で0
★シグマ座標の利点は下端境界条件の単純さ、弱点は山岳上空の気圧傾度力誤差
★実務ではハイブリッド気圧座標が主流
★鉛直層は地表付近と圏界面付近を密に配置する`,
