        title: '時間積分と計算安定性（CFL条件）',
        emoji: '⏱️',
        body: `▼ゼロから：モデルは現在の状態から少し先の状態を計算し、それを繰り返して未来へ進みます。この「少し先」の刻み幅を時間ステップといいます。刻み幅を大きくすれば速く先まで計算できますが、大きすぎると計算が発散して数値がとんでもない値に飛んでしまいます。「1ステップの間に、情報が格子1個分より遠くへ行ってはいけない」というのが有名なCFL条件です。バケツリレーで、隣の人を飛び越して荷物を渡せないのと同じ理屈です。

━━━━━━━━━━━━━━━━━━━━━━
🔑 CFL条件の意味
━━━━━━━━━━━━━━━━━━━━━━
・条件式：（伝播速度×時間ステップ）÷格子間隔 が1以下
・この比をクーラン数と呼ぶ
・破ると計算が不安定になり、振幅が指数的に増大して破綻する
→ 制約を決めるのは最も速い波。大気中で最も速いのは音波（約340m/s）と外部重力波（数百m/s）
→ 音波が制約になるのを避けるため、非静力学モデルでは音波だけ短い刻みで解く分離法（時間分割法）を使う

【図解】CFL条件の計算例（格子間隔と最大風速から許される時間ステップを求める）
　条件｜数値｜備考｜
　格子間隔｜5000m｜メソモデル相当｜
　最大伝播速度｜100m/s｜上層ジェット相当｜
　式｜時間ステップ＝格子間隔÷速度｜クーラン数1の限界｜
　答え｜50秒以下｜実際は余裕を見て短くする｜
　⚠ 音波を陽に解く場合は速度340m/sで評価するので、同じ格子では約15秒以下となる

━━━━━━━━━━━━━━━━━━━━━━
🔑 時間積分のスキーム
━━━━━━━━━━━━━━━━━━━━━━
・オイラー法…単純だが精度が低く不安定になりやすい
・リープフロッグ法（蛙飛び法）…前後2時刻を使う。計算モードという偽の解が現れるため時間フィルタを併用する
・陰解法…未来の値を含む式を連立で解く。計算量は増えるがCFL条件の制約を大きく緩められる
・セミラグランジュ法…格子点に到達する空気塊の出発点をさかのぼって値を内挿する。移流に対して長い時間ステップが取れる
→ 現在の全球モデルはセミラグランジュ法と半陰解法を組み合わせ、格子20kmでも数分の時間ステップを実現している

━━━━━━━━━━━━━━━━━━━━━━
🔑 数値拡散と平滑化
━━━━━━━━━━━━━━━━━━━━━━
・格子で表せない小さい波にエネルギーが溜まると計算が荒れる
・そこで人工的な水平拡散を加えて短波長成分を減衰させる
・かけすぎると本来表現すべき前線の傾度まで鈍ってしまう
→ 「数値拡散は物理ではなく計算安定化の手段」と理解する

━━━━━━━━━━━━━━━━━━━━━━
🔑 初期ショックとスピンアップ
━━━━━━━━━━━━━━━━━━━━━━
・初期値には観測と解析の都合で、風と気圧のつり合いが崩れた成分が含まれる
・そのまま積分を始めると、大振幅の重力波が発生して場が揺れる。これを初期ショックという
・対策…初期値化（イニシャライゼーション）で不要な重力波成分を取り除く
・また、雲や降水はモデル内で作られるため、積分開始から数時間は降水が過小になる。これをスピンアップという
→ 予報初期の1時間から3時間の降水量が実況より少ないのはスピンアップの影響であることが多い
→ 対策として、レーダーや衛星から推定した降水を同化して初期の雲・降水場を作る手法が導入されている

━━━━━━━━━━━━━━━━━━━━━━
🔑 予報時間と計算コストの関係
━━━━━━━━━━━━━━━━━━━━━━
・1回の予報の計算量は、格子数×鉛直層数×ステップ数に比例する
・計算例：格子間隔5km、時間ステップ50秒で6時間予報を行う場合のステップ数
　　式：ステップ数＝予報時間÷時間ステップ
　　代入：6×3600秒÷50秒
　　答え：432ステップ
→ 予報時間を2倍にすればステップ数も2倍、単純に計算時間も2倍になる
→ 発表までの制限時間があるため、分解能と予報時間はトレードオフの関係になる

━━━━━━━━━━━━━━━━━━━━━━
🔑 頻出のひっかけ
━━━━━━━━━━━━━━━━━━━━━━
・「格子間隔を半分にしても時間ステップは変えなくてよい」→ × 陽解法では時間ステップも半分にする必要がある
・「CFL条件を満たせば必ず正確な解が得られる」→ × 安定性の条件であって精度の保証ではない
・「セミラグランジュ法は質量を厳密に保存する」→ × 保存性の確保には別の工夫が必要
・「計算が発散したのは初期値が悪いから」→ 必ずしも正しくない。時間ステップと格子の関係が原因のことも多い

━━━━━━━━━━━━━━━━━━━━━━
🔑 過去問での問われ方
━━━━━━━━━━━━━━━━━━━━━━
・「格子間隔と時間ステップの関係として適切なものを選べ」という問題。格子を細かくすれば時間ステップも短くする必要があるという方向を押さえる
・「予報初期に降水量が実況より少なくなる理由を述べよ」という記述問題。モデル内で雲と降水が形成されるまでに時間がかかるスピンアップが答えの核になる
・「初期値化を行う目的として適切なものを選べ」という問題。つり合いの崩れによって生じる不要な重力波を除く点が正解
・数値計算の安定性については、クーラン数の定義そのものを計算させる出題もある。単位を揃えてから割ることを忘れない

★ここだけ暗記
★CFL条件はクーラン数（速度×時間ステップ÷格子間隔）が1以下
★制約を決めるのは最速の波、音波や外部重力波
★セミラグランジュ法と半陰解法で長い時間ステップが可能
★数値拡散は安定化の手段であり物理過程ではない`,
