        emoji: '🧊',
        body: `▼ゼロから：積乱雲の中では空気が毎秒10メートル以上の速さで駆け上がります。このとき鉛直方向には強い加速度が働いており、「気圧傾度力と重力がつり合っている」という静力学の仮定は通用しません。水平20kmの格子では積乱雲そのものはひとつの格子に収まってしまい問題になりませんが、水平5kmや2kmまで細かくすると、モデル自身が対流を表現しはじめます。そのとき必要になるのが非静力学モデルです。

━━━━━━━━━━━━━━━━━━━━━━
🔑 静力学近似が成り立つ条件
━━━━━━━━━━━━━━━━━━━━━━
・現象の水平スケールが鉛直スケール（対流圏の厚さ約10km）より十分大きいこと
・目安として水平スケールが数十km以上あれば静力学近似は良い近似
→ 温帯低気圧や前線帯（水平1000km規模）では完全に成立
→ 積乱雲（水平10km規模）では成立しない

━━━━━━━━━━━━━━━━━━━━━━
🔑 非静力学モデルの特徴
━━━━━━━━━━━━━━━━━━━━━━
・鉛直の運動方程式をそのまま解き、鉛直加速度を予報する
・音波が解に含まれるため、時間ステップの制約が厳しい
・対策として、音波成分だけを短い刻みで解く時間分割法や、音波を人工的に遅くする手法を使う
・雲物理過程を詳細に扱い、雨・雪・あられ・雲水・雲氷などを個別に予報する
→ 気象庁のメソモデルと局地モデルは非静力学モデル

【図解】静力学モデルと非静力学モデルの使い分け
　項目｜静力学モデル｜非静力学モデル｜
　典型格子｜20km前後｜5km以下｜
　鉛直流｜連続の式から診断｜方程式で予報｜
　積乱雲｜パラメタリゼーション｜一部を直接表現｜
　時間ステップ｜数分｜数十秒｜
　⚠ 格子5kmは積乱雲を「解像できそうで解像できない」灰色領域で、対流パラメタリゼーションの扱いが難しい

━━━━━━━━━━━━━━━━━━━━━━
🔑 灰色領域（グレーゾーン）の問題
━━━━━━━━━━━━━━━━━━━━━━
・積乱雲の直径は数kmから10km程度
・格子5kmでは、対流を格子で表現するには粗く、パラメタリゼーションで表現するには細かい
・格子で無理に表現すると、個々の対流セルが大きく描かれ降水が強すぎたり遅れたりする
→ 現業では格子5kmのメソモデルでも対流パラメタリゼーションを併用する構成が取られてきた
→ 格子2km以下になると対流をほぼ直接表現できるとみなされる

━━━━━━━━━━━━━━━━━━━━━━
🔑 非静力学モデルが扱える現象
━━━━━━━━━━━━━━━━━━━━━━
・積乱雲の発達と衰弱、降水セルの移動
・山越え気流と山岳波、局地的な下降流
・海陸風、山谷風などの局地循環
・線状降水帯の形成と維持（環境場が正しければ位置と強度をある程度再現）
→ いずれも水平スケールが数kmから数十kmの現象で、静力学モデルでは表現できない
→ ただし発生時刻と位置には誤差が残り、実況の監視と組み合わせて使うのが原則

━━━━━━━━━━━━━━━━━━━━━━
🔑 側面境界条件（ネスティング）
━━━━━━━━━━━━━━━━━━━━━━
・領域モデルは地球の一部だけを計算するので、領域の縁の値を外から与える必要がある
・親モデル（全球モデル）の予報値を時間内挿して境界に与える方式をネスティングという
→ 親モデルの誤差が境界から入り込み、時間とともに領域内部へ伝わる
→ そのため領域モデルの予報時間は、親モデルの誤差が内部を覆う前の範囲に限られる
→ メソモデルの予報時間が全球モデルより短いのは、計算コストだけでなくこの理由による
→ 領域の縁の付近には緩和領域を設け、内部の解と境界値を滑らかにつなぐ

━━━━━━━━━━━━━━━━━━━━━━
🔑 頻出のひっかけ
━━━━━━━━━━━━━━━━━━━━━━
・「非静力学モデルなら竜巻も予測できる」→ × 竜巻の直径は数十mから数百mで、格子2kmでも直接表現はできない。親雲の環境場までが限界
・「静力学モデルは鉛直流を計算しない」→ × 連続の式から診断する。予報変数として解かないだけ
・「格子を細かくすれば対流パラメタリゼーションは不要」→ 2km以下でほぼ不要とされるが、5km前後では併用が必要
・「非静力学モデルは音波を無視している」→ × 含んでおり、それが時間ステップの制約になる

━━━━━━━━━━━━━━━━━━━━━━
🔑 過去問での問われ方
━━━━━━━━━━━━━━━━━━━━━━
・「静力学近似が成り立つ現象として適切なものを選べ」という問題。温帯低気圧や前線帯は成立、積乱雲やダウンバーストは不成立
・「領域モデルの予報時間が全球モデルより短い理由を述べよ」という記述問題。側面境界から親モデルの情報しか入らず、その誤差が内部へ伝わるためと書くのが型
・「非静力学モデルで新たに予報される量を選べ」という問題。鉛直速度が正解
・実技では、メソモデルと局地モデルの格子と予報時間を示し、どちらを使うべきかを判断させる出題がある。数時間先の激しい現象なら局地モデル、半日先までの降水分布ならメソモデルが基本

★ここだけ暗記
★静力学近似は水平スケールが鉛直スケールより十分大きいときに有効
★積乱雲を扱うメソ・局地モデルは非静力学
★非静力学モデルの制約は音波、対策は時間分割法
★格子5km前後は灰色領域で対流の扱いが難しい`,
