・「衛星の輝度温度を直接同化する利点を述べよ」という記述。気温や水蒸気に変換する過程で生じる誤差や情報の損失を避けられると書く
・「3次元変分法と4次元変分法の違いとして適切なものを選べ」という問題。時間次元を含むかどうかが答え
・変分法という語は学科専門でほぼ毎回登場するため、評価関数の構造を一文で言えるようにしておく

