・「4次元変分法の説明として適切なものを選べ」という問題がほぼ定番。時間方向を含めて観測に整合する初期値を求める点が正解
・「同化ウィンドウ」という用語の意味を問う問題
・「4次元変分法が3次元変分法より優れている点を述べよ」という記述。観測を正しい時刻で扱えるため、移動する擾乱の位置や強度の解析精度が上がると書く
・接線形モデルと随伴モデルの役割を入れ替えた誤選択肢が作られやすいので、順方向と逆方向の対応を覚える

