        title: '観測データの品質管理',
        emoji: '🔍',
        body: `▼ゼロから：観測データは必ずしも正しい値とは限りません。測器の故障、通信の途中での文字化け、位置情報の誤り、船舶の観測位置のずれなど、間違いはいくらでも起こります。誤った観測をそのまま同化すると、そこだけ架空の低気圧ができるといった深刻な悪影響が出ます。しかも数値予報は自動処理なので、人が一件ずつ確認することはできません。そこで機械的にふるいにかける仕組みが必要になります。それが品質管理です。

━━━━━━━━━━━━━━━━━━━━━━
🔑 品質管理の主なチェック
━━━━━━━━━━━━━━━━━━━━━━
・形式チェック…通報の書式、日時、位置、単位が正しいか
・気候学的チェック…その季節・場所としてありえない値でないか
・整合性チェック…同じ地点の他要素と矛盾しないか。気温より露点が高いなど
・時間的連続性チェック…前の時刻から急変しすぎていないか
・空間的整合性チェック…周囲の観測点と大きくかけ離れていないか
・第一推定値チェック…第一推定値との差が、想定される誤差の範囲を超えていないか
→ 最後の第一推定値チェックが最も強力で、実質的な主役

━━━━━━━━━━━━━━━━━━━━━━
🔑 第一推定値チェックの考え方
━━━━━━━━━━━━━━━━━━━━━━
・観測値と第一推定値の差を、観測誤差と背景誤差から見積もった標準偏差で割る
・その値が一定のしきい値を超えたら棄却する
・計算例：観測22.0度、第一推定値18.0度、想定される差の標準偏差1.5度、しきい値3
　　式：規格化した差＝差÷標準偏差
　　代入：4.0÷1.5
　　答え：約2.7で、しきい値3を下回るので採用される
→ しきい値を厳しくすると、本物の急変を捨ててしまう危険がある
→ 逆に緩めると誤った観測が入り込む。両者のバランスが難しい

【図解】品質管理の落とし穴
　状況｜起こること｜対応｜
　しきい値が厳しい｜真の急変を棄却｜擾乱を見逃す｜
　しきい値が緩い｜誤観測が混入｜解析が壊れる｜
　背景が大きく外れている｜正しい観測を棄却｜連続棄却の監視｜
　⚠ 台風の中心付近など、背景と観測が大きくずれる場面ほど正しい観測が捨てられやすい

━━━━━━━━━━━━━━━━━━━━━━
🔑 間引きと重複除去
━━━━━━━━━━━━━━━━━━━━━━
・衛星観測などは格子より高密度で得られるが、すべては使わない
・理由…隣り合う観測の誤差は互いに相関しており、独立でない情報を重複して使うと解析が偏る
・そこで一定間隔で間引き（シニング）して使う
・同一の観測が複数経路で届くこともあるため、重複の除去も行う
→ 「観測は多ければ多いほどよい」わけではないことを示す代表例

━━━━━━━━━━━━━━━━━━━━━━
🔑 モニタリングとブラックリスト
━━━━━━━━━━━━━━━━━━━━━━
・各観測点について、第一推定値との差の平均と標準偏差を継続的に監視する
・恒常的に偏っている測点や、頻繁に棄却される測点は要注意として扱う
・悪質な場合はブラックリストに載せ、同化から除外する
→ 観測の質の監視は数値予報センターの重要な日常業務
→ 観測所側にも情報が返され、測器の点検につながる

━━━━━━━━━━━━━━━━━━━━━━
🔑 代表性誤差という考え方
━━━━━━━━━━━━━━━━━━━━━━
・格子が代表するのは、たとえば20km四方の平均的な状態である
・一方、観測が測っているのはその一点の値
・盆地の底の気温、山の稜線の風速などは、格子平均とは大きく違う
・この差は測器の誤差ではないが、同化の立場では誤差として扱うしかない
→ これを代表性誤差といい、観測誤差の一部として与える
→ 地上気温や地上風は代表性誤差が大きいため、同化での重みを小さくするか、そもそも使わない場合がある
→ 逆に地上気圧は水平方向に滑らかで代表性誤差が小さく、同化での価値が高い

━━━━━━━━━━━━━━━━━━━━━━
🔑 観測の時刻と位置の誤り
━━━━━━━━━━━━━━━━━━━━━━
・船舶やブイでは、通報される位置が実際とずれる事例がある
・航空機観測では、機体ごとに気温に偏りが出ることが知られている
・ラジオゾンデでは、日射による気温センサーの昇温を補正する必要がある
→ 観測の癖を種類ごとに把握しておくことが、品質管理の設計に直結する

━━━━━━━━━━━━━━━━━━━━━━
🔑 頻出のひっかけ
━━━━━━━━━━━━━━━━━━━━━━
・「品質管理では観測値の誤りだけを取り除く」→ × 正しい観測が棄却されることもある
・「高密度の観測はすべて同化したほうがよい」→ × 誤差相関のため間引く
・「第一推定値チェックは第一推定値が正しいことを前提とする」→ 前提ではないが依存はする。背景が大きく外れると正しい観測を捨てる
・「品質管理は人手で行う」→ × 自動処理が基本、監視は人が行う

━━━━━━━━━━━━━━━━━━━━━━
🔑 過去問での問われ方
━━━━━━━━━━━━━━━━━━━━━━
・「データ同化における品質管理の目的として適切なものを選べ」という問題
・「高密度観測を間引いて使う理由を述べよ」という記述。近接する観測の誤差が相関しており、独立な情報として扱えないためと書く
・「品質管理によって正しい観測が棄却される場合があるのはどのようなときか」という記述。第一推定値が実況から大きく外れている場合と答える
・観測の種類ごとの特性（船舶は位置誤差、ラジオゾンデは日射補正）を絡めた出題もある

★ここだけ暗記
★品質管理の主役は第一推定値チェック
★しきい値は厳しすぎても緩すぎても害がある
★高密度観測は誤差相関のため間引いて使う
★恒常的に偏る観測はモニタリングで検出しブラックリスト化する`,
