        body: `▼ゼロから：「明日は晴れのち曇り、所により一時雨」。この短い文には、細かい約束事が詰まっています。「のち」と「時々」は違いますし、「所により」には明確な定義があります。同じ言葉が人によって違う意味に受け取られては情報になりません。だから気象庁は予報用語を定め、その使い方を統一しています。用語の定義を覚えることは、そのまま試験対策になります。

━━━━━━━━━━━━━━━━━━━━━━
🔑 時間的な変化を表す用語
━━━━━━━━━━━━━━━━━━━━━━
・のち…期間の前と後で天気が変わる。前半と後半で異なる状態
・時々…その現象が現れる時間の合計が、予報期間の2分の1未満
・一時…その現象が連続して現れ、その時間が予報期間の4分の1未満
→ 「時々」は断続的、「一時」は連続的という違いがある
→ 割合の分母は予報期間であり、時間の長さの絶対値ではない

━━━━━━━━━━━━━━━━━━━━━━
🔑 空間的な広がりを表す用語
━━━━━━━━━━━━━━━━━━━━━━
・所により…現象が現れる地域が、予報区全体の50パーセント未満で、その分布が定まっていない場合
・広い範囲で…予報区の大部分に現象が現れる場合
・地域を限定する表現…山沿い、平野部、沿岸部など、あらかじめ定義された区域を用いる
→ 「所により」は場所を特定できないことを示す表現
→ 場所が特定できるなら、山沿いなどの具体的な表現を使う

━━━━━━━━━━━━━━━━━━━━━━
🔑 天気の表現
━━━━━━━━━━━━━━━━━━━━━━
・快晴…雲量が1以下
・晴れ…雲量が2以上8以下
・曇り…雲量が9以上
・天気予報では「快晴」は使わず「晴れ」にまとめる
→ 雲量の基準は観測上の定義であり、予報の表現とは扱いが異なる
→ 予報では晴れ・曇り・雨・雪とその組み合わせで表す

━━━━━━━━━━━━━━━━━━━━━━
🔑 程度を表す用語
━━━━━━━━━━━━━━━━━━━━━━
・雨の強さ…やや強い雨（1時間10mm以上20mm未満）、強い雨（20mm以上30mm未満）、激しい雨（30mm以上50mm未満）、非常に激しい雨（50mm以上80mm未満）、猛烈な雨（80mm以上）
・風の強さ…やや強い風（10メートル毎秒以上15メートル毎秒未満）、強い風（15以上20未満）、非常に強い風（20以上30未満）、猛烈な風（30以上）
→ 数値と用語の対応は頻出。境目の数値を正確に覚える
→ 予報文では、こうした用語を使って現象の程度を伝える

【図解】時間と空間の用語の整理
　用語｜意味する割合｜連続性｜
　時々｜2分の1未満｜断続的｜
　一時｜4分の1未満｜連続的｜
　所により｜50パーセント未満｜場所が不定｜
　⚠ 「時々」と「一時」は割合だけでなく連続性でも区別される

━━━━━━━━━━━━━━━━━━━━━━
🔑 使わない言葉
━━━━━━━━━━━━━━━━━━━━━━
・あいまいで人によって解釈が分かれる言葉は避ける
・専門的すぎて一般に伝わらない言葉も避けるか、言い換える
・恐怖をあおるだけで行動につながらない表現も避ける
→ 一方で、危険が差し迫っている場合には、強い言葉であっても明確に伝える
→ 「命を守る行動を」といった表現は、行動を促す目的で用いられる

━━━━━━━━━━━━━━━━━━━━━━
🔑 雪に関する用語
━━━━━━━━━━━━━━━━━━━━━━
・やや強い雪…1時間降雪量が3cm以上5cm未満に相当する程度
・強い雪…1時間降雪量が5cm以上に相当する程度
・大雪…災害が発生するおそれのある雪
・猛吹雪…雪を伴った猛烈な風で、視程が著しく悪化する状態
→ 雪は降雪量（積もる深さ）と降水量（水に換算した量）を区別する
→ 積雪の深さは、降った量から融けた量と圧密による沈降を差し引いた結果

━━━━━━━━━━━━━━━━━━━━━━
🔑 予報文を組み立てる順序
━━━━━━━━━━━━━━━━━━━━━━
・まず期間全体の主たる天気を述べる
・次に変化を「のち」で示す
・断続的な現象を「時々」、短時間の現象を「一時」で加える
・場所が限られる現象を「所により」または地域名で加える
→ 例…「晴れのち曇り、夜遅く所により雨」という形になる
→ 順序と用語の使い分けが定まっているので、慣れれば機械的に組める

━━━━━━━━━━━━━━━━━━━━━━
🔑 頻出のひっかけ
━━━━━━━━━━━━━━━━━━━━━━
・「一時は予報期間の2分の1未満」→ × 4分の1未満
・「時々は連続して現れる場合」→ × 断続的
・「所によりは予報区の一部で必ず降ること」→ 場所を特定できない場合の表現
・「1時間30mmの雨は強い雨」→ × 激しい雨

━━━━━━━━━━━━━━━━━━━━━━
🔑 過去問での問われ方
━━━━━━━━━━━━━━━━━━━━━━
・「予報用語の説明として適切なものを選べ」という定番問題。時々と一時の割合が頻出
・「1時間降水量と表現の対応として適切なものを選べ」という問題
・「風速と表現の対応」を問う問題
・実技では、与えられた状況に対して適切な予報文を作らせる、あるいは不適切な表現を指摘させる設問が出る

★ここだけ暗記
★時々は2分の1未満で断続的、一時は4分の1未満で連続的
★所によりは50パーセント未満で場所が特定できない場合
★雨は10・20・30・50・80mmで区分、風は10・15・20・30メートル毎秒で区分
★用語の定義を統一することで、情報の受け取り方のばらつきを防ぐ`,
