・警戒レベルとの対応付け…情報がどの行動に対応するかを数字で示す
・危険度分布…色分けにより、自分のいる場所の危険度が一目で分かる
・平易な言葉…専門用語を避け、行動を促す表現を使う
・過去の災害との比較…「何年の災害に匹敵する」という表現で規模を伝える
