・「湿数3度以下の領域を塗りつぶし、雲域との対応を述べよ」という作業問題
・「下層ジェットが大雨に果たす役割を述べよ」という記述。暖湿気を大量に供給し、収束により上昇流を強めると書く
・冬季には「850hPa気温から降雪の可能性を判断せよ」という設問が出る

