        title: '相当温位と気団の判別',
        emoji: '🔥',
        body: `▼ゼロから：空気の暖かさを比べるとき、気温だけでは足りません。上昇すれば冷え、下降すれば暖まるからです。そこで基準の高さに直した温位を使いますが、水蒸気を含む空気では、凝結したときに出る熱も考えに入れなければ本当の性質は分かりません。それを含めたのが相当温位です。梅雨前線の解析で気温ではなく相当温位を使うのは、こういう理由です。

━━━━━━━━━━━━━━━━━━━━━━
🔑 温位と相当温位
━━━━━━━━━━━━━━━━━━━━━━
・温位…空気塊を1000hPaまで乾燥断熱的に移したときの気温。乾燥断熱変化では保存される
・相当温位…含まれる水蒸気をすべて凝結させ、その潜熱で加熱したうえで1000hPaに戻したときの気温
・相当温位は、乾燥断熱変化でも湿潤断熱変化でも保存される
→ 空気塊の「素性」を表す量として、追跡に適している
→ 温位が同じでも、湿っているほうが相当温位は高い

━━━━━━━━━━━━━━━━━━━━━━
🔑 相当温位で何が分かるか
━━━━━━━━━━━━━━━━━━━━━━
・高相当温位…暖かく湿った空気。大雨の材料
・低相当温位…冷たい、または乾いた空気
・相当温位の水平傾度が大きい帯…前線帯
・相当温位が上へ行くほど下がる層…対流不安定
→ 梅雨前線は気温の差が小さいことがあるが、相当温位の差は明瞭
→ そのため梅雨前線の解析には850hPaの相当温位図を使う

━━━━━━━━━━━━━━━━━━━━━━
🔑 対流不安定
━━━━━━━━━━━━━━━━━━━━━━
・相当温位が高度とともに減少する状態
・つまり下層が湿って暖かく、上層が乾いて冷たい状態
・この層全体が持ち上げられると、下層が先に飽和して不安定が顕在化する
→ 下層の暖湿気の流入と、上層の乾燥空気の流入が重なると危険
→ 集中豪雨の環境場として、実技で繰り返し問われる

━━━━━━━━━━━━━━━━━━━━━━
🔑 数値の目安
━━━━━━━━━━━━━━━━━━━━━━
・850hPaの相当温位が340K以上…暖湿気が流入している目安
・345Kから350K以上…大雨の可能性が高まる目安
・相当温位の集中帯…等値線が込み合っている帯で、前線に対応する
→ 数値は季節と地域で変わるが、340Kという値は判断の起点として覚えておく
→ 相当温位の高い空気がどこから来ているかを、風の場からたどるのが実技の作業

━━━━━━━━━━━━━━━━━━━━━━
🔑 相当温位と風の組み合わせ
━━━━━━━━━━━━━━━━━━━━━━
・高相当温位の空気を運ぶ強い風があれば、暖湿気の大量の供給が起こる
・その空気が山や前線にぶつかって持ち上げられれば、大雨になる
・相当温位の集中帯に沿って風が吹いていれば、前線に沿った流入
→ 「どこから、どれだけの水蒸気が、どのように持ち上がるか」の三点で考える
→ 実技の記述では、この三点を押さえた答案が求められる

【図解】相当温位から読むこと
　状況｜相当温位の分布｜示すこと｜
　暖湿気の流入｜下層で高い値の舌状の張り出し｜大雨の材料｜
　前線帯｜水平方向に密な等値線｜前線の位置｜
　対流不安定｜上ほど低い値｜対流の発生しやすさ｜
　乾燥した寒気｜低い値｜安定化と下降流｜
　⚠ 相当温位が高いだけでは雨にならない。持ち上げる仕組みが必要

━━━━━━━━━━━━━━━━━━━━━━
🔑 湿球温位という近い量
━━━━━━━━━━━━━━━━━━━━━━
・湿球温位も、乾燥断熱と湿潤断熱の両方で保存される量
・相当温位と一対一に対応するので、どちらを使っても判断は同じ
・相当温位は数値が大きく、湿球温位は摂氏に近い値になる
→ 図によってどちらが使われているか確認する
→ 保存量であるという性質が、気団の追跡に役立つ点は共通

━━━━━━━━━━━━━━━━━━━━━━
🔑 相当温位の鉛直断面図
━━━━━━━━━━━━━━━━━━━━━━
・横軸に距離、縦軸に気圧をとり、相当温位の等値線を描いた図
・前線面は、等相当温位線が斜めに傾いた帯として現れる
・下層に高相当温位の空気が入り込み、その上に低相当温位の層が乗る形が対流不安定
→ 前線面の傾きから、温暖前線か寒冷前線かを判断できる
→ 実技では断面図を読み、前線面の位置と対流不安定の層を答えさせる設問が出る

━━━━━━━━━━━━━━━━━━━━━━
🔑 頻出のひっかけ
━━━━━━━━━━━━━━━━━━━━━━
・「相当温位は湿潤断熱変化では保存されない」→ × 保存される
・「相当温位が高いほど必ず雨が降る」→ × 上昇の仕組みが必要
・「対流不安定は相当温位が上ほど高い状態」→ × 上ほど低い状態
・「温位と相当温位は同じもの」→ × 潜熱を含むかどうかが違う

━━━━━━━━━━━━━━━━━━━━━━
🔑 過去問での問われ方
━━━━━━━━━━━━━━━━━━━━━━
・「850hPa相当温位図から前線の位置を解析せよ」という作業問題
・「相当温位345K以上の領域を図示し、暖湿気の流入経路を述べよ」という設問
・「対流不安定な成層になっている理由を、相当温位の鉛直分布から述べよ」という記述
・「相当温位が保存量である理由を述べよ」という知識問題も出る

★ここだけ暗記
★相当温位は乾燥断熱でも湿潤断熱でも保存される
★梅雨前線は気温より相当温位の集中帯で判断する
★対流不安定は相当温位が上ほど低い成層
★850hPa相当温位340K以上が暖湿気流入の目安`,
