【図解】上昇流と湿りの組み合わせ
　鉛直p速度｜湿数｜予想される降水｜
　強い上昇流｜小さい｜まとまった降水｜
　強い上昇流｜大きい｜降水は少ない｜
　弱い上昇流｜小さい｜弱い降水か曇り｜
　下降流｜大きい｜晴天｜
