━━━━━━━━━━━━━━━━━━━━━━
・対流有効位置エネルギー…自由対流高度から平衡高度までの間で、空気塊が周囲より暖かい部分の面積に対応する。積乱雲の潜在的な強さを表す
・対流抑制…地表から自由対流高度までの間で、空気塊が周囲より冷たい部分の面積。対流を始めるために必要な持ち上げの大きさを表す
・目安…対流有効位置エネルギーが1000ジュール毎キログラム以上で対流が活発、2500以上で激しい対流
