・「メソサイクロンが形成される仕組みを述べよ」という記述。鉛直シアーによる水平渦が上昇流で立ち起こされると書く
・「フックエコーが示すことを述べよ」という記述
・「スーパーセルが長時間持続する理由を述べよ」という記述。上昇流と下降流が分離しているためと答える

